import time
import numpy as np

def evaluate_model(model, test_data, metrics=['accuracy', 'speed']):
    results = {}

    # Accuracy evaluation
    if 'accuracy' in metrics:
        correct = 0
        for item in test_data:
            prediction = model.predict(item['input'])
            if prediction == item['expected']:
                correct += 1
        results['accuracy'] = correct / len(test_data)

    # Speed evaluation
    if 'speed' in metrics:
        start_time = time.time()
        for item in test_data[:100]:  # Test on subset for speed
            model.predict(item['input'])
        elapsed = time.time() - start_time
        results['speed'] = 100 / elapsed  # predictions per second

    return results
